  st.textContent = "/* Totore: disegni di Francesco. In piedi un disegno unico con zampe e coda che si muovono; seduta e addormentata intere */\n#totore{position:fixed;left:0;right:0;bottom:0;height:190px;pointer-events:none;z-index:5;overflow:hidden}\n.tt-walk{position:absolute;left:0;bottom:0;width:114px;height:93px;will-change:transform}\n.tt-cat{position:relative;width:114px;height:93px;pointer-events:auto;cursor:pointer;display:block;filter:drop-shadow(0 4px 5px rgba(0,0,0,.16))}\n.tt-cat img,.tt-sleep img{position:absolute;display:block;max-width:none;pointer-events:none;-webkit-user-select:none;user-select:none}\n.tt-walk.sx .tt-cat{transform:scaleX(-1)}\n.tt-corpo{position:absolute;inset:0}\n.tt-l1{--a:8deg}.tt-l2{--a:10deg}.tt-l3{--a:10deg}.tt-l4{--a:6deg}\n.tt-tail{animation:ttcoda 2.2s ease-in-out infinite alternate}\n.tt-cat .tt-siede{display:none;left:-2px;bottom:0;width:118px;height:100px;transform-origin:50% 100%;animation:ttrespiro 3.4s ease-in-out infinite}\n.seduta .tt-corpo{display:none}.seduta .tt-cat .tt-siede{display:block}\n.cammina .tt-l1,.cammina .tt-l4{animation:ttpasso .5s ease-in-out infinite alternate}\n.cammina .tt-l2,.cammina .tt-l3{animation:ttpasso .5s ease-in-out infinite alternate-reverse}\n.cammina .tt-corpo{animation:ttondeggia .25s ease-in-out infinite alternate}\n.fusa .tt-cat{animation:ttfusa .18s linear 8}\n.salto .tt-cat{animation:ttsalto .6s ease-out}\n.salto .tt-l1,.salto .tt-l2{animation:none;transform:rotate(16deg)}.salto .tt-l3,.salto .tt-l4{animation:none;transform:rotate(-18deg)}\n.spavento .tt-cat{animation:ttspavento .5s ease-out}\n.sbuca{animation:ttsbuca 2.2s ease-in-out both}\n.tt-fumetto{position:absolute;bottom:100px;left:62px;background:var(--sup);color:var(--ink);border:1px solid var(--linea);border-radius:12px;padding:3px 9px;font-weight:700;font-size:.86rem;white-space:nowrap;box-shadow:var(--shadow, 0 4px 12px rgba(0,0,0,.15))}\n.tt-home{margin-left:auto;align-self:flex-end;border:0;background:none;padding:0;cursor:pointer;width:128px;flex:none}\n.tt-sleep{position:relative;width:128px;height:41px;display:block}\n.tt-sleep img{left:0;bottom:0;width:100%;height:100%}\n.tt-breath{transform-origin:50% 100%;animation:ttrespiro 3.2s ease-in-out infinite}\n.tt-z{position:absolute;right:6px;top:-10px;font:700 12px inherit;color:var(--muted);animation:ttz 3s ease-in-out infinite;opacity:0}.tt-z2{right:-2px;top:-20px;animation-delay:1.5s}\n.tt-home.sveglia .tt-sleep{animation:ttstira .9s ease-in-out}\n@keyframes ttpasso{from{transform:rotate(calc(var(--a, 10deg) * -1))}to{transform:rotate(var(--a, 10deg))}}\n@keyframes ttondeggia{from{translate:0 0}to{translate:0 -1.5px}}\n@keyframes ttcoda{from{transform:rotate(-5deg)}to{transform:rotate(7deg)}}\n@keyframes ttguarda{0%,70%,100%{transform:rotate(0)}76%,84%{transform:rotate(-7deg)}90%{transform:rotate(3deg)}}\n@keyframes ttfusa{0%{translate:0 0}50%{translate:1px -1px}100%{translate:-1px 0}}\n@keyframes ttsalto{0%,100%{translate:0 0}40%{translate:0 -26px}}\n@keyframes ttspavento{0%{scale:1}30%{scale:1.12 1.2;translate:0 -10px}100%{scale:1;translate:0 0}}\n@keyframes ttsbuca{0%{translate:0 100px}22%,80%{translate:0 0}100%{translate:0 100px}}\n@keyframes ttrespiro{0%,100%{scale:1 1}50%{scale:1.01 1.035}}\n@keyframes ttz{0%{opacity:0;translate:0 6px}30%{opacity:1}100%{opacity:0;translate:4px -10px}}\n@keyframes ttstira{0%,100%{transform:scaleX(1)}50%{transform:scaleX(1.1) translateY(-2px)}}\n\n/* Totore: altre scene */\n.tt-walk{--dir:1}.tt-walk.sx{--dir:-1}\n.tt-nap{display:none;position:absolute;left:0;bottom:0;width:151px;height:48px;pointer-events:auto;cursor:pointer;filter:drop-shadow(0 3px 4px rgba(0,0,0,.14))}\n.tt-nap .tt-sleep{width:151px;height:48px}\n.pisolino .tt-cat{display:none}.pisolino .tt-nap{display:block}\n.sx .tt-nap{transform:scaleX(-1)}\n.corre .tt-l1,.corre .tt-l2,.corre .tt-l3,.corre .tt-l4{animation-duration:.18s!important}\n.corre .tt-cat{animation:ttondeggia .18s ease-in-out infinite alternate}\n.corre .tt-leg{--a:18deg}\n.corre .tt-tail{animation:none;transform:rotate(-12deg)}\n.stira .tt-cat{transform-origin:50% 100%;animation:ttstirati 2.2s ease-in-out}\n.stira .tt-l3,.stira .tt-l4{animation:ttallunga 2.2s ease-in-out}\n.stira .tt-tail{animation:ttcodasu 2.2s ease-in-out}\n.tt-farfalla{position:absolute;left:0;bottom:0;pointer-events:none}\n.tt-ali{transform-box:fill-box;transform-origin:center;animation:ttali .16s ease-in-out infinite alternate}\n.tt-cuore{position:absolute;bottom:70px;color:#e2777a;font-size:16px;pointer-events:none;animation:ttcuore 2s ease-out forwards;opacity:0}\n.tt-home .tt-sleep{animation:ttsogno 9s ease-in-out infinite}\n@keyframes ttstirati{0%,100%{rotate:0deg;scale:1 1}35%,70%{rotate:calc(8deg * var(--dir));scale:1.07 .95}}\n@keyframes ttallunga{0%,100%{transform:rotate(0)}35%,70%{transform:rotate(-24deg)}}\n@keyframes ttcodasu{0%,100%{transform:rotate(0)}35%,70%{transform:rotate(-14deg)}}\n@keyframes ttali{from{transform:scaleX(1)}to{transform:scaleX(.25)}}\n@keyframes ttcuore{0%{opacity:0;translate:0 0}15%{opacity:1}100%{opacity:0;translate:6px -60px}}\n@keyframes ttsogno{0%,88%,100%{rotate:0deg}91%{rotate:-2deg}94%{rotate:1.5deg}}\n@media (prefers-reduced-motion: reduce){.tt-breath,.tt-z,.tt-tail,.tt-siede,.tt-home .tt-sleep{animation:none}}\n#totore .tt-cat,#totore .tt-nap{pointer-events:none}\n#totore{bottom:0}\n";
